SELECT ss.store_id, CASE WHEN YEAR(ss.sale_date) < 2024 THEN 'before_2024' WHEN YEAR(ss.sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, COUNT(i.quantity) AS quantity_count, MAX(i.last_restock) AS latest_last_restock FROM inventory i LEFT JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE ss.product_id IN (3, 4) GROUP BY ss.store_id, CASE WHEN YEAR(ss.sale_date) < 2024 THEN 'before_2024' WHEN YEAR(ss.sale_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY latest_last_restock, ss.store_id DESC, sale_cohort LIMIT 5
